using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    // ── FormatPhoneNumber ──────────────────────────────────────────

    [TestMethod]
    public void FormatPhoneNumber_ReturnsCorrectFormat()
    {
        var result = _formatter.FormatPhoneNumber("1234567890");

        Assert.AreEqual("(123) 456-7890", result);
        StringAssert.StartsWith(result, "(123)");
        StringAssert.EndsWith(result, "7890");
        StringAssert.Contains(result, "456");
    }

    [TestMethod]
    public void FormatPhoneNumber_AreaCodeIsWrappedInParentheses()
    {
        var result = _formatter.FormatPhoneNumber("8005551234");

        StringAssert.StartsWith(result, "(800)");
        StringAssert.Matches(result, new(@"^\(\d{3}\) \d{3}-\d{4}$"));
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _formatter.FormatPhoneNumber(null!));
    }

    [TestMethod]
    public void FormatPhoneNumber_WrongLength_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.FormatPhoneNumber("12345"));
    }

    // ── BuildGreeting ──────────────────────────────────────────────

    [TestMethod]
    public void BuildGreeting_DefaultTitle_StartsWithDearMr()
    {
        var result = _formatter.BuildGreeting("Smith");

        StringAssert.StartsWith(result, "Dear Mr.");
        StringAssert.EndsWith(result, "Smith,");
        Assert.AreEqual("Dear Mr. Smith,", result);
    }

    [TestMethod]
    public void BuildGreeting_CustomTitle_UsesProvidedTitle()
    {
        var result = _formatter.BuildGreeting("Johnson", "Dr.");

        StringAssert.StartsWith(result, "Dear Dr.");
        StringAssert.EndsWith(result, "Johnson,");
    }

    [TestMethod]
    public void BuildGreeting_EndsWithComma()
    {
        var result = _formatter.BuildGreeting("Doe");

        StringAssert.EndsWith(result, ",");
    }

    [TestMethod]
    public void BuildGreeting_NullOrWhitespace_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.BuildGreeting(""));
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.BuildGreeting("   "));
    }

    // ── GenerateSlug ───────────────────────────────────────────────

    [TestMethod]
    public void GenerateSlug_SimpleTitleBecomesLowercaseWithDashes()
    {
        var result = _formatter.GenerateSlug("Hello World");

        Assert.AreEqual("hello-world", result);
        StringAssert.Matches(result, new(@"^[a-z0-9\-]+$"));
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharactersAreReplacedByDashes()
    {
        var result = _formatter.GenerateSlug("C# is Awesome!!!");

        StringAssert.StartsWith(result, "c-");
        StringAssert.EndsWith(result, "awesome");
        StringAssert.DoesNotMatch(result, new(@"[^a-z0-9\-]"));
    }

    [TestMethod]
    public void GenerateSlug_LeadingTrailingWhitespace_IsTrimmed()
    {
        var result = _formatter.GenerateSlug("  Spaced Out  ");

        Assert.AreEqual("spaced-out", result);
    }

    [TestMethod]
    public void GenerateSlug_ConsecutiveSpecialChars_CollapseToDash()
    {
        var result = _formatter.GenerateSlug("foo---bar   baz");

        Assert.AreEqual("foo-bar-baz", result);
    }

    [TestMethod]
    public void GenerateSlug_NullOrWhitespace_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.GenerateSlug(""));
    }

    // ── FormatCurrency ─────────────────────────────────────────────

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(19.99m);

        StringAssert.StartsWith(result, "$");
        Assert.AreEqual("$19.99", result);
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_StartsWithSymbol()
    {
        var result = _formatter.FormatCurrency(100m, "€");

        StringAssert.StartsWith(result, "€");
        StringAssert.EndsWith(result, "100.00");
    }

    [TestMethod]
    public void FormatCurrency_AlwaysShowsTwoDecimalPlaces()
    {
        var result = _formatter.FormatCurrency(5m);

        StringAssert.EndsWith(result, ".00");
        Assert.AreEqual("$5.00", result);
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount_FormatsCorrectly()
    {
        var result = _formatter.FormatCurrency(-42.5m);

        StringAssert.StartsWith(result, "$-");
        StringAssert.EndsWith(result, "42.50");
    }
}

